//! Helpers for writing checked-in generated files.

use std::fs;
use std::path::Path;

use anyhow::{bail, Context};

/// Prepends the header that marks `text` as generated by `cargo xtask {command}`.
pub(crate) fn add_preamble(command: &str, text: &str) -> String {
    format!("//! Generated by `cargo xtask {command}`, do not edit by hand.\n{text}")
}

/// Ensures `path` contains `contents`, ignoring CRLF vs LF differences.
///
/// In `check` mode a mismatch is an error; otherwise the file is (re)written.
pub(crate) fn ensure_file_contents(
    command: &str,
    path: &Path,
    contents: &str,
    check: bool,
) -> anyhow::Result<()> {
    if let Ok(existing) = fs::read_to_string(path) {
        if normalize_newlines(&existing) == normalize_newlines(contents) {
            return Ok(());
        }
    }
    if check {
        bail!(
            "{} is not up to date; run `cargo xtask {command}` and commit the result",
            path.display()
        );
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, contents).with_context(|| format!("writing {}", path.display()))?;
    eprintln!("updated {}", path.display());
    Ok(())
}

fn normalize_newlines(s: &str) -> String {
    s.replace("\r\n", "\n")
}
